function paintTiger(sprite,palette,frame){
 const runs=TIGER_SHEET_FRAMES[frame];
 if(!runs)throw new RangeError('Unknown tiger frame: '+frame);
 let pixel=0;
 for(let i=0;i<runs.length;i+=2){const count=runs[i],color=runs[i+1];if(color)for(let k=0;k<count;k++){const p=pixel+k;sprite.set(p%TIGER_ART.W,Math.floor(p/TIGER_ART.W),TIGER_SHEET_PALETTE[color]);}pixel+=count;}
}

// Shared pixel geometry used by the spider and beetle.
function tigerSmooth(t) { t = Math.max(0, Math.min(1, t)); return t * t * (3 - 2 * t); }

function tigerCapsule(cv, A, ra, B, rb, p, pick) {
  const x0 = Math.floor(Math.min(A[0] - ra, B[0] - rb)), x1 = Math.ceil(Math.max(A[0] + ra, B[0] + rb));
  const y0 = Math.floor(Math.min(A[1] - ra, B[1] - rb)), y1 = Math.ceil(Math.max(A[1] + ra, B[1] + rb));
  const dx = B[0] - A[0], dy = B[1] - A[1], L2 = dx * dx + dy * dy || 1, L = Math.sqrt(L2);
  for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) {
    const px = x + 0.5 - A[0], py = y + 0.5 - A[1], t = Math.max(0, Math.min(1, (px * dx + py * dy) / L2));
    const ex = px - dx * t, ey = py - dy * t, r = ra + (rb - ra) * t, d = Math.hypot(ex, ey);
    if (d > r) continue;
    // lado: +1 na borda esquerda do osso (lado da luz), -1 na direita
    const side = (ex * dy - ey * dx) / L / r;
    cv.put(x, y, pick(t, side, x, y), p);
  }
}

function tigerEllipse(cv, cx, cy, rx, ry, p, pick) {
  for (let y = Math.floor(cy - ry); y <= Math.ceil(cy + ry); y++) for (let x = Math.floor(cx - rx); x <= Math.ceil(cx + rx); x++) {
    const dx = (x + 0.5 - cx) / rx, dy = (y + 0.5 - cy) / ry;
    if (dx * dx + dy * dy <= 1) cv.put(x, y, pick(dx, dy, x, y), p);
  }
}
